# These names are configuration-only specializations of one polymorphic Lean function.
check(api.echo_nat_box(box) == box)
check(api.echo_again(api.NatBoxAgain(4, 1)) == api.NatBoxAgain(4, 1))
check(api.echo_text_box(api.TextBox(greeting, 0)) == api.TextBox(greeting, 0))
check(api.echo_left(api.LeftBox(5, 2)) == api.LeftBox(5, 2))
check(api.echo_right(api.RightBox(6, 3)) == api.RightBox(6, 3))
check(api.LeftBox is not api.RightBox and api.LeftBox is not api.NatBox)
check(api.echo_boxes(boxes) == tuple(boxes) and api.echo_boxes([]) == ())
check(api.echo_optional_boxes(Some(boxes)) == Some(tuple(boxes)))
check(api.echo_optional_boxes(None) is None and api.echo_optional_boxes(Some([])) == Some(()))
check(api.echo_nats([0, 2**70]) == (0, 2**70) and api.echo_nats([]) == ())
check(api.echo_optional_nat(Some(2**70)) == Some(2**70) and api.echo_optional_nat(None) is None)
check(rejected(lambda: api.echo_left(api.RightBox(5, 2))))
check(rejected(lambda: api.echo_boxes([api.NatBoxAgain(1, 0)])))
check(rejected(lambda: api.echo_optional_boxes(Some([api.NatBox(-1, 0)]))))
check(rejected(lambda: api.echo_nats([1, '2'])))
check(rejected(lambda: api.echo_optional_nat(Some(-1))))
check(api.echo_left(api.LeftBox(7, 0)).value == 7)
